/* Concept Energy Optioneering: service worker for the installable web app (PWA).
 * Generated by packaging/pwa/build-pwa.mjs from sw.template.js; edit the template, not the copy in out/pwa.
 *
 * - The cache name carries VERSION, a hash of index.html and the other shell files, so every new build installs a new
 *   cache. The new worker then waits; the page shows an "Update ready - reload" notice and only reloads when the user
 *   asks (message SKIP_WAITING), so a model run is never cut short. Closing every window of the app also applies it.
 * - Cache-first: the app shell is served from the cache (works offline). The network update is the browser's check
 *   for a changed sw.js, made on every load and, from the page, when the app comes back into view and hourly.
 * - Only this app's own URLs are handled. The site can host other pages on the same origin and path (GitHub Pages
 *   project sites share https://<user>.github.io), so navigations to other pages and all other requests go to the
 *   network untouched, and only this app's caches (prefix + scope path) are ever deleted.
 */
'use strict';

const VERSION = '%%VERSION%%';
const SHELL = /*%%SHELL%%*/ [];
const PREFIX = 'ceo-shell';
const SCOPE_PATH = new URL('./', self.location.href).pathname;
const CACHE = `${PREFIX}:${SCOPE_PATH}:${VERSION}`;
const INDEX_URL = new URL('index.html', self.location.href).href;
const APP_PATHS = new Set([SCOPE_PATH, new URL(INDEX_URL).pathname]);
const SHELL_PATHS = new Set(SHELL.map((u) => new URL(u, self.location.href).pathname));

self.addEventListener('install', (event) => {
  // cache: 'reload' skips the HTTP cache (GitHub Pages sends max-age=600) so the new cache holds this build's files.
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(SHELL.map((u) => new Request(u, { cache: 'reload' })))));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const mine = `${PREFIX}:${SCOPE_PATH}:`;
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith(mine) && k !== CACHE).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  const data = event.data || {};
  if (data.type === 'SKIP_WAITING') self.skipWaiting();
  else if (data.type === 'GET_VERSION' && event.ports && event.ports[0]) event.ports[0].postMessage({ version: VERSION, cache: CACHE });
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (req.mode === 'navigate') {
    if (!APP_PATHS.has(url.pathname)) return; // another page on the same site: not ours
    event.respondWith(cacheFirst(INDEX_URL, req));
    return;
  }
  if (!SHELL_PATHS.has(url.pathname)) return;
  event.respondWith(cacheFirst(url.origin + url.pathname, req));
});

async function cacheFirst(key, req) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(key, { ignoreSearch: true });
  if (hit) return hit;
  // Not in the cache (for example, storage was cleared while this worker stayed active): fetch and keep a copy.
  const res = await fetch(req);
  if (res && res.ok && res.type === 'basic') await cache.put(key, res.clone());
  return res;
}
